"""Annihilators, subgroup duality and uncertainty extremals.

For a subgroup H of a finite abelian group G, the annihilator is
    H^perp = { psi in dual(G) : psi(x) = 1 for all x in H }.
Two facts drive everything:

    1_H^ = |H| . 1_{H^perp}          (orthogonality over a subgroup)
    |H| . |H^perp| = |G|             (Plancherel applied to 1_H)

Consequently every function of the form f(x) = c . chi(x) . 1_H(x - a) with c nonzero
satisfies |supp f| . |supp f^| = |G| exactly: it is extremal for the uncertainty
principle |supp f| . |supp f^| >= |G|.

Cost: subgroup closure O(|H| . #generators); annihilator test O(|G| . |H|).
"""

from __future__ import annotations

import cmath
import itertools
import math
from typing import Dict, List, Sequence, Tuple

Elem = Tuple[int, ...]
Func = Dict[Elem, complex]


def elements(moduli: Sequence[int]) -> List[Elem]:
    return [tuple(t) for t in itertools.product(*(range(n) for n in moduli))]


def add(moduli: Sequence[int], x: Elem, y: Elem) -> Elem:
    return tuple((a + b) % n for a, b, n in zip(x, y, moduli))


def sub(moduli: Sequence[int], x: Elem, y: Elem) -> Elem:
    return tuple((a - b) % n for a, b, n in zip(x, y, moduli))


def character_value(moduli: Sequence[int], k: Elem, x: Elem) -> complex:
    phase = sum(2.0 * math.pi * kj * xj / nj for kj, xj, nj in zip(k, x, moduli))
    return cmath.exp(1j * phase)


def subgroup_generated(moduli: Sequence[int], gens: Sequence[Elem]) -> List[Elem]:
    """Closure of {gens} under addition: the subgroup they generate."""
    zero = tuple(0 for _ in moduli)
    H, frontier = {zero}, [zero]
    while frontier:
        h = frontier.pop()
        for g in gens:
            k = add(moduli, h, g)
            if k not in H:
                H.add(k)
                frontier.append(k)
    return sorted(H)


def annihilator(moduli: Sequence[int], H: Sequence[Elem]) -> List[Elem]:
    """All characters trivial on H, indexed by the dual group (identified with G)."""
    return [k for k in elements(moduli)
            if all(abs(character_value(moduli, k, h) - 1) < 1e-9 for h in H)]


def dft(moduli: Sequence[int], f: Func) -> Func:
    G = elements(moduli)
    return {k: sum(character_value(moduli, k, x).conjugate() * f[x] for x in G) for k in G}


def support_product(moduli: Sequence[int], f: Func) -> int:
    """|supp f| . |supp f^|, the quantity bounded below by |G|."""
    F = dft(moduli, f)
    s1 = sum(1 for v in f.values() if abs(v) > 1e-9)
    s2 = sum(1 for v in F.values() if abs(v) > 1e-9)
    return s1 * s2


def modulated_coset(moduli: Sequence[int], H: Sequence[Elem], a: Elem,
                    chi: Elem, c: complex) -> Func:
    """f(x) = c . chi(x) . 1_H(x - a): the general conjectured extremal."""
    Hs = set(H)
    return {x: (c * character_value(moduli, chi, x) if sub(moduli, x, a) in Hs else 0j)
            for x in elements(moduli)}


if __name__ == "__main__":
    moduli = [12]
    N = len(elements(moduli))
    for gen in [(1,), (2,), (3,), (4,), (6,), (0,)]:
        H = subgroup_generated(moduli, [gen])
        A = annihilator(moduli, H)
        f = modulated_coset(moduli, H, (1,), (3,), 2 - 1j)
        print(f"H = <{gen[0]:2d}>  |H| = {len(H):2d}  |H^perp| = {len(A):2d}  "
              f"product = {len(H) * len(A):2d}  "
              f"extremal modulated coset: {support_product(moduli, f) == N}")
